ID do Chamado: {{ $('Loop Over Items').item.json.chamado_atual.id }}
Título: {{ $('Loop Over Items').item.json.chamado_atual.titulo }}
Descrição: {{ $('Loop Over Items').item.json.chamado_atual.descricao }}
