parameters.jsCode:
return $input.all().map(item => {
  try {
    let dados = item.json;
    if (dados?.content?.parts?.[0]?.text) { dados = JSON.parse(dados.content.parts[0].text); }
    if (dados?.message?.content) { try { dados = JSON.parse(dados.message.content); } catch(e) {} }
    const chamadoOriginal = $('13. Preparar Dados para Classificacao').first().json.chamado;
    return { json: { chamado: chamadoOriginal, classificacao: dados.classificacao || 'ERRO', executor: dados.executor || 'ERRO', justificativa_tecnica: dados.justificativa_tecnica || 'Sem justificativa', palavras_chave: dados.palavras_chave_identificadas || [] } };
  } catch (error) {
    return { json: { classificacao: 'ERRO', executor: 'ERRO', erro: error.message } };
  }
});

const saidaPadrao = {
  ...$('09. Preparar Alerta de Duplicidade ao Fiscal').first().json,
  decisao_fiscal: '',
  origem_decisao: 'sem_registro'
};

const bruto = $input.first().json;
const lista = Array.isArray(bruto)
  ? bruto
  : (Array.isArray(bruto.data) ? bruto.data : (Array.isArray(bruto['hydra:member']) ? bruto['hydra:member'] : []));

function textoFollowup(item) {
  return String(item?.content || item?.comment || item?.name || '').toUpperCase();
}

const elegiveis = lista
  .map((f) => ({
    data: new Date(f?.date_mod || f?.date_creation || f?.date || 0).getTime() || 0,
    texto: textoFollowup(f),
    bruto: f
  }))
  .filter((f) => f.texto.includes('DECISAO_DUPLICIDADE='))
  .sort((a, b) => b.data - a.data);

if (elegiveis.length === 0) {
  return [{ json: saidaPadrao }];
}

const ultimo = elegiveis[0].texto;
let decisao = '';
if (ultimo.includes('DECISAO_DUPLICIDADE=CONFIRMAR')) {
  decisao = 'confirma_duplicado';
} else if (ultimo.includes('DECISAO_DUPLICIDADE=NAO_DUPLICADO')) {
  decisao = 'nao_duplicado';
}

return [{
  json: {
    ...$('09. Preparar Alerta de Duplicidade ao Fiscal').first().json,
    decisao_fiscal: decisao,
    origem_decisao: decisao ? 'followup_glpi' : 'sem_registro_valido'
  }
}];

return $input.all().map(item => {
  const tentativa = Number(item.json.tentativa_reprocesso_dup || 0) + 1;
  return {
    json: {
      ...item.json,
      tentativa_reprocesso_dup: tentativa,
      reprocessar_dup: tentativa <= 2
    }
  };
});

return $input.all().map(item => {
  const tentativa = Number(item.json.tentativa_reprocesso_class || 0) + 1;
  return {
    json: {
      ...item.json,
      tentativa_reprocesso_class: tentativa,
      reprocessar_class: tentativa <= 1
    }
  };
});

const entradas = $input.all().map((i) => i.json);

const dados = entradas.flatMap((r) => {
  if (Array.isArray(r?.data)) return r.data;
  if (Array.isArray(r?.body?.data)) return r.body.data;
  if (Array.isArray(r)) return r;
  return [];
});

if (!Array.isArray(dados) || dados.length === 0) {
  return [{ json: { erro: 'Nenhum chamado encontrado', total: 0 } }];
}

const MAX_CHAMADOS_TRIAGEM = 3;
const MAX_HISTORICO_COMPARACAO = 25;
const agora = new Date();
const corte90Dias = new Date(agora.getTime() - 90 * 24 * 60 * 60 * 1000);
const corte7Dias = new Date(agora.getTime() - 7 * 24 * 60 * 60 * 1000);

function statusNumero(status) {
  if (typeof status === 'number') return status;
  const txt = String(status || '').toLowerCase();
  if (txt.includes('2') || txt.includes('atribu')) return 2;
  if (txt.includes('3') || txt.includes('planejad')) return 3;
  if (txt.includes('4') || txt.includes('pendent')) return 4;
  if (txt.includes('5') || txt.includes('finaliz') || txt.includes('solucion')) return 5;
  return Number(status) || null;
}

function parseData(valor) {
  const d = new Date(valor);
  return Number.isNaN(d.getTime()) ? null : d;
}

function toEpoch(valor) {
  const d = parseData(valor);
  return d ? d.getTime() : 0;
}

const todosLimpos = dados.map(c => ({
  id: c['2'] || c.id,
  titulo: c['1'] || c.name || '',
  status: c['12'] || c.status,
  status_num: statusNumero(c['12'] || c.status),
  descricao: (c['21'] || c.content || '').replace(/<[^>]*>/g, '').trim(),
  localizacao: c['83'] || c.locations_id || '',
  data_abertura: c['15'] || c.date || '',
  solicitante: c['4'] || c.users_id_recipient || '',
  email_solicitante: c['22'] || ''
}));

const elegiveisHistorico = todosLimpos.filter(c => {
  const dataAbertura = parseData(c.data_abertura);
  if (!c.status_num) return false;
  if (c.status_num === 4) return true;
  if ([2, 3, 5].includes(c.status_num)) {
    return !!dataAbertura && dataAbertura >= corte90Dias;
  }
  return false;
});

const chamadosParaTriar = elegiveisHistorico
  .filter(c => {
    const dataAbertura = parseData(c.data_abertura);
    if (![2, 3, 4].includes(c.status_num)) return false;
    if (!dataAbertura) return false;
    return dataAbertura >= corte7Dias;
  })
  .sort((a, b) => toEpoch(b.data_abertura) - toEpoch(a.data_abertura))
  .slice(0, MAX_CHAMADOS_TRIAGEM);

if (chamadosParaTriar.length === 0) {
  return [{ json: { erro: 'Nenhum chamado elegivel para triagem de duplicidade no recorte atual', total_historico: elegiveisHistorico.length } }];
}

const itensSaida = chamadosParaTriar.map(chamadoAtual => {
  const historicoCompacto = elegiveisHistorico
    .filter(c => String(c.id) !== String(chamadoAtual.id))
    .sort((a, b) => toEpoch(b.data_abertura) - toEpoch(a.data_abertura))
    .slice(0, MAX_HISTORICO_COMPARACAO);

  return {
    json: {
      chamado_atual: chamadoAtual,
      historico_abertos: historicoCompacto,
      recorte_status: {
        historico_90_dias: [2, 3, 5],
        historico_todos: [4],
        triar_prioridade: [2, 3, 4],
        limite_chamados_triar: MAX_CHAMADOS_TRIAGEM,
        limite_historico_comparacao: MAX_HISTORICO_COMPARACAO
      }
    }
  };
});

return itensSaida.map((item, idx) => ({
  json: {
    ...item.json,
    _split_index: idx + 1,
    _split_total: itensSaida.length,
    _anotacao_mudanca: '2026-03-19: no 04 ajustado para quebrar lista em itens individuais'
  }
}));

return $input.all().map(item => {
  try {
    let dados = item.json;
    const bruto = JSON.stringify(dados).slice(0, 2000);

    if (dados?.content?.parts?.[0]?.text) {
      dados = JSON.parse(dados.content.parts[0].text);
    }
    if (dados?.message?.content) {
      try { dados = JSON.parse(dados.message.content); } catch(e) {}
    }

    if (dados?.chamado && dados?.duplicidade) {
      return { json: { ...dados, _erro: false } };
    }

    if (dados?.eh_duplicado !== undefined || dados?.potencial_duplicata !== undefined) {
      return {
        json: {
          chamado: dados.chamado || { id: 'desconhecido' },
          duplicidade: {
            eh_duplicado: !!(dados.eh_duplicado || dados.potencial_duplicata),
            chamado_referencia_id: dados.chamado_referencia_id || null,
            caracteristicas_match: dados.caracteristicas_match || [],
            justificativa_para_fiscal: dados.justificativa_para_fiscal || 'Sem justificativa'
          },
          _erro: false
        }
      };
    }

    return {
      json: {
        chamado: dados?.chamado || { id: 'estrutura_invalida' },
        duplicidade: {
          eh_duplicado: false,
          chamado_referencia_id: null,
          caracteristicas_match: [],
          justificativa_para_fiscal: 'Resposta da IA sem estrutura esperada.'
        },
        _erro: true,
        tipo_erro: 'estrutura_resposta_inesperada',
        payload_ia_bruto: bruto
      }
    };
  } catch (error) {
    return {
      json: {
        chamado: { id: 'erro_parse' },
        duplicidade: {
          eh_duplicado: false,
          chamado_referencia_id: null,
          caracteristicas_match: [],
          justificativa_para_fiscal: 'Erro ao processar resposta da IA: ' + error.message
        },
        _erro: true,
        tipo_erro: 'parse_json_ia',
        payload_ia_bruto: JSON.stringify(item.json).slice(0, 2000),
        detalhe_erro: error.message
      }
    };
  }
});

const item = $input.first().json;
const chamado = item.chamado;
const dup = item.duplicidade;

// Modo operacional: true = ambiente de teste (permite seguir sem decisao do fiscal), false = producao (nao classifica sem decisao do fiscal).
const MODO_TESTE = true;

const instrucoes = [
  'DECISAO_DUPLICIDADE=CONFIRMAR  -> para fechar como duplicado',
  'DECISAO_DUPLICIDADE=NAO_DUPLICADO -> para seguir classificacao',
  'Responda em um acompanhamento (followup) deste chamado.'
].join('\n');

return [{
  json: {
    ...item,
    _modo_teste: MODO_TESTE,
    _chamado_id: chamado.id,
    _chamado_ref_id: dup.chamado_referencia_id,
    _formulario_titulo: 'Alerta de Duplicidade - Chamado #' + chamado.id,
    _formulario_mensagem: 'A IA identificou o chamado #' + chamado.id + ' ("' + chamado.titulo + '") como possivel duplicata do chamado #' + (dup.chamado_referencia_id || 'N/A') + '.',
    _instrucoes_fiscal: instrucoes,
    _mensagem_followup_fiscal: [
      '[TRIAGEM_IA] Possivel duplicidade detectada.',
      'Chamado atual: #' + chamado.id + ' - ' + (chamado.titulo || ''),
      'Chamado de referencia: #' + (dup.chamado_referencia_id || 'N/A'),
      'Justificativa IA: ' + (dup.justificativa_para_fiscal || 'Sem justificativa'),
