  const chamadoRecuperado = $('04. Estruturar Dados dos Chamados').itemMatching(i)?.json?.chamado_atual || json.chamado_atual || json._chamado_recuperado;
  const historicoRecuperado = $('04. Estruturar Dados dos Chamados').itemMatching(i)?.json?.historico_abertos || json.historico_abertos;

