return $input.all().map((item, i) => {
  const json = item.json || {};
  const tentativa = Number(json.tentativa_reprocesso_dup || 0) + 1;
  const reprocessar = tentativa <= 2;

  const base = baseEstruturada[i]?.json || {};
  const chamadoRecuperado = base.chamado_atual || json.chamado_atual || json._chamado_recuperado || null;
  const historicoRecuperado = base.historico_abertos || json.historico_abertos || [];

  return {
    json: {
      ...json,
      tentativa_reprocesso_dup: tentativa,
      reprocessar_dup: reprocessar,
