const baseEstruturada = $('04. Estruturar Dados dos Chamados').all();

return $input.all().map((item, i) => {
  const json = item.json || {};
  const tentativa = Number(json.tentativa_reprocesso_dup || 0) + 1;
  const reprocessar = tentativa <= 2;

  const base = baseEstruturada[i]?.json || {};
  const chamadoRecuperado = base.chamado_atual || json.chamado_atual || json._chamado_recuperado || null;
  const historicoRecuperado = base.historico_abertos || json.historico_abertos || [];

  return {
    json: {
      ...json,
      tentativa_reprocesso_dup: tentativa,
      reprocessar_dup: reprocessar,
      chamado_atual: chamadoRecuperado,
      historico_abertos: historicoRecuperado,
    }
  };
});

return $input.all().map(item => {
  const tentativa = Number(item.json.tentativa_reprocesso_class || 0) + 1;
  return {
    json: {
      ...item.json,
      tentativa_reprocesso_class: tentativa,
      reprocessar_class: tentativa <= 1
    }
  };
});

// Processa todos os itens de entrada e extrai a lista de chamados retornada pelo GLPI
let todosChamados = [];

for (const item of $input.all()) {
  let dadosBrutos = item.json;
  let lista = [];

  if (Array.isArray(dadosBrutos.data)) lista = dadosBrutos.data;
  else if (dadosBrutos.body && Array.isArray(dadosBrutos.body.data)) lista = dadosBrutos.body.data;
  else if (Array.isArray(dadosBrutos)) lista = dadosBrutos;
  else if (Array.isArray(dadosBrutos['hydra:member'])) lista = dadosBrutos['hydra:member'];
  else {
    for (const key in dadosBrutos) {
      if (Array.isArray(dadosBrutos[key])) { lista = dadosBrutos[key]; break; }
    }
    if (lista.length === 0) lista = [dadosBrutos];
  }

  lista.forEach(c => todosChamados.push(c));
}

if (todosChamados.length === 0) {
  return [{ json: { erro: 'Nenhum chamado encontrado', total: 0 } }];
}

// Manual: processa backlog em lotes (mais antigos primeiro) para evitar starvation.
// Webhook: sempre processa apenas o ticket do evento.
const LIMITE_CHAMADOS_TRIAGEM_MANUAL = 5;
const MAX_HISTORICO_COMPARACAO = 25;
const DIAS_FINALIZADO_3_MESES = 90;
const EVENTOS_WEBHOOK_PROCESSAVEIS = ['new'];

const agora = new Date();
const corteFinalizado3Meses = new Date(agora.getTime() - DIAS_FINALIZADO_3_MESES * 24 * 60 * 60 * 1000);

const STATUS_LABELS = { 1: 'Novo', 2: 'Processando Atribuido', 3: 'Processando Planejado', 4: 'Pendente', 5: 'Finalizado', 6: 'Fechado' };

function statusNumero(status) {
  if (typeof status === 'number') return status;
  const txt = String(status || '').toLowerCase();
  if (txt.includes('novo') || txt === '1') return 1;
  if (txt.includes('atribu') || txt === '2') return 2;
  if (txt.includes('planejad') || txt === '3') return 3;
  if (txt.includes('pendent') || txt === '4') return 4;
  if (txt.includes('finaliz') || txt.includes('solucion') || txt === '5') return 5;
  if (txt.includes('fechado') || txt.includes('close') || txt === '6') return 6;
  return Number(status) || null;
}

function toEpoch(valor) {
  const d = new Date(valor);
  return Number.isNaN(d.getTime()) ? 0 : d.getTime();
}

function entraNoRecorteHistorico(chamado) {
  const dAbertura = new Date(chamado.data_abertura);
  const dataValida = !Number.isNaN(dAbertura.getTime());

  if ([2, 3, 4].includes(chamado.status_num)) return true;

  if (chamado.status_num === 5) {
    return dataValida && dAbertura >= corteFinalizado3Meses;
  }

  return false;
}

function entraNaTriagemAtiva(chamado) {
  return chamado.status_num === 1;
}

function extrairTipoServico(c) {
  return c.tipo_servico || c.tipo || c.service_type || c['14'] || c.itilcategories_id || c['itilcategories_id'] || '';
}

const todosLimpos = todosChamados.map(c => {
  const status_num = statusNumero(c['12'] || c.status);
  const dataAbertura = c['15'] || c.date || '';
  return {
    id: c['2'] || c.id,
    titulo: c['1'] || c.name || '',
    status: c['12'] || c.status,
    status_num,
    status_nome: STATUS_LABELS[status_num] || 'Desconhecido',
    tipo_servico: extrairTipoServico(c),
    descricao: (c['21'] || c.content || '').replace(/<[^>]*>/g, '').trim(),
    localizacao: c['83'] || c.locations_id || '',
    data_abertura: dataAbertura,
    data_hora_abertura: dataAbertura,
    solicitante: c['4'] || c.users_id_recipient || '',
    email_solicitante: c['22'] || ''
  };
});

const elegiveisHistorico = todosLimpos.filter(entraNoRecorteHistorico);

let chamadosParaTriar = todosLimpos
  .filter(entraNaTriagemAtiva)
  .sort((a, b) => toEpoch(a.data_abertura) - toEpoch(b.data_abertura));

let ticketIdEvento = null;
let eventoTipo = null;
let modoExecucao = 'manual';

try {
  const evento = $('02b. Preparar Entrada Webhook').first().json || {};
  const n = Number(evento._ticket_id_evento);
  if (Number.isFinite(n) && n > 0) ticketIdEvento = n;
  eventoTipo = String(evento._webhook_evento_tipo || '').toLowerCase();
} catch {}

if (ticketIdEvento) {
  modoExecucao = 'webhook';

  if (eventoTipo && !EVENTOS_WEBHOOK_PROCESSAVEIS.includes(eventoTipo)) {
    return [{
      json: {
        erro: 'Evento de webhook ignorado por politica anti-reprocesso',
        ticket_id_evento: ticketIdEvento,
        evento_tipo: eventoTipo,
        modo_execucao: modoExecucao
      }
    }];
  }

  const alvo = todosLimpos.find((c) => String(c.id) === String(ticketIdEvento));
  if (!alvo) {
    return [{
      json: {
        erro: 'Chamado do webhook nao encontrado na busca de interesse',
        ticket_id_evento: ticketIdEvento,
        total_historico: elegiveisHistorico.length,
        modo_execucao: modoExecucao
      }
    }];
  }

  if (alvo.status_num !== 1) {
    return [{
      json: {
        erro: 'Chamado do webhook nao esta com status Novo (1)',
        ticket_id_evento: ticketIdEvento,
        status_atual: alvo.status_num,
        modo_execucao: modoExecucao
      }
    }];
  }

  chamadosParaTriar = [alvo];
} else if (LIMITE_CHAMADOS_TRIAGEM_MANUAL > 0) {
  chamadosParaTriar = chamadosParaTriar.slice(0, LIMITE_CHAMADOS_TRIAGEM_MANUAL);
}

if (chamadosParaTriar.length === 0) {
  return [{
    json: {
      erro: 'Nenhum chamado Novo elegivel para triagem ativa de duplicidade',
      total_historico: elegiveisHistorico.length,
      modo_execucao: modoExecucao
    }
  }];
}

const itemsDeSaida = [];

for (let i = 0; i < chamadosParaTriar.length; i++) {
  const chamadoAtual = chamadosParaTriar[i];
  const historicoCompacto = elegiveisHistorico
    .filter(c => String(c.id) !== String(chamadoAtual.id))
    .sort((a, b) => toEpoch(b.data_abertura) - toEpoch(a.data_abertura))
    .slice(0, MAX_HISTORICO_COMPARACAO);

  itemsDeSaida.push({
    json: {
      chamado_atual: chamadoAtual,
      historico_abertos: historicoCompacto,
      _split_index: i + 1,
      _split_total: chamadosParaTriar.length,
      _chamado_recuperado: chamadoAtual,
      _modo_execucao: modoExecucao,
      _ticket_id_evento: ticketIdEvento,
      _webhook_evento_tipo: eventoTipo || null
    }
  });
}

return itemsDeSaida;

const entradas = $input.all();
const originais = $('04. Estruturar Dados dos Chamados').all();

function tentarParseJson(texto) {
  if (typeof texto !== 'string') return null;
  try {
    return JSON.parse(texto);
  } catch {
    return null;
  }
}

function extrairCarga(jsonEntrada) {
  let dados = jsonEntrada;

  const textoPart = dados?.content?.parts?.[0]?.text;
  if (typeof textoPart === 'string') {
    const parsed = tentarParseJson(textoPart);
    if (parsed !== null) dados = parsed;
  }

  const textoMsg = dados?.message?.content;
  if (typeof textoMsg === 'string') {
    const parsed = tentarParseJson(textoMsg);
    if (parsed !== null) dados = parsed;
  }

  return dados;
}

function pareceResultadoDuplicidade(obj) {
  if (!obj || typeof obj !== 'object') return false;
  if (obj.duplicidade && typeof obj.duplicidade === 'object') return true;
  if (obj.eh_duplicado !== undefined) return true;
  if (obj.potencial_duplicata !== undefined) return true;
  return false;
}

function extrairRegistrosOrdenados(payload) {
  if (Array.isArray(payload)) return payload;
  if (payload && Array.isArray(payload.resultados)) return payload.resultados;
  if (payload && Array.isArray(payload.items)) return payload.items;

  if (payload && Array.isArray(payload.data)) {
    const data = payload.data;
    if (data.every((x) => pareceResultadoDuplicidade(x) || (x && x.chamado))) {
      return data;
    }
  }

  return [payload];
}

function parseBool(valor) {
  if (typeof valor === 'boolean') return valor;
  if (typeof valor === 'number') return valor !== 0;
  if (typeof valor === 'string') {
    const v = valor.trim().toLowerCase();
    if (['true', '1', 'sim', 'yes', 'y', 'verdadeiro'].includes(v)) return true;
    if (['false', '0', 'nao', 'no', 'n', 'falso'].includes(v)) return false;
  }
  return false;
}

function normalizarChamado(chamado, original) {
  const base = chamado && typeof chamado === 'object' ? chamado : {};
  const ref = original && typeof original === 'object' ? original : {};
  return { ...ref, ...base };
}

function dataMs(valor) {
  const d = new Date(valor || '');
  return Number.isNaN(d.getTime()) ? 0 : d.getTime();
}

function normalizarTexto(txt) {
  return String(txt || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function tokens(txt) {
  const stop = new Set(['de','da','do','das','dos','a','o','e','em','na','no','para','com','sem','por','um','uma']);
  return normalizarTexto(txt)
    .split(' ')
    .filter(t => t.length > 2 && !stop.has(t));
}

function intersecaoCount(a, b) {
  const sa = new Set(a);
  let c = 0;
  for (const t of b) {
    if (sa.has(t)) c++;
  }
  return c;
}

function escolherManterFechar(chamadoAtual, candidato) {
  const atualId = chamadoAtual?.id || null;
  const candId = candidato?.id || null;

  const atualStatus = Number(chamadoAtual?.status_num || 0);
  const candStatus = Number(candidato?.status_num || 0);
  const emProcessamento = new Set([2, 3, 4]);

  if (candId && emProcessamento.has(candStatus) && !emProcessamento.has(atualStatus)) {
    return { manter: candId, fechar: atualId, criterio: 'manter_em_processamento' };
  }

  if (atualId && emProcessamento.has(atualStatus) && !emProcessamento.has(candStatus)) {
    return { manter: atualId, fechar: candId, criterio: 'manter_em_processamento' };
  }

  const dAtual = dataMs(chamadoAtual?.data_hora_abertura || chamadoAtual?.data_abertura);
  const dCand = dataMs(candidato?.data_hora_abertura || candidato?.data_abertura);

  if (dCand > 0 && dAtual > 0) {
    if (dCand <= dAtual) {
      return { manter: candId, fechar: atualId, criterio: 'manter_mais_antigo' };
    }
    return { manter: atualId, fechar: candId, criterio: 'manter_mais_antigo' };
  }

  return { manter: candId || atualId, fechar: atualId, criterio: 'manter_referencia_ia' };
}

function montarCandidatos(chamado, historico, referenciaId, ehDuplicado) {
  if (!ehDuplicado) return [];

  const tAtual = tokens((chamado?.titulo || '') + ' ' + (chamado?.descricao || ''));
  const localAtual = normalizarTexto(chamado?.localizacao);
  const servAtual = normalizarTexto(chamado?.tipo_servico);
  const refStr = referenciaId ? String(referenciaId) : null;

  const ranked = [];

  for (const h of historico) {
    if (!h?.id) continue;
    if (String(h.id) === String(chamado?.id)) continue;

    let score = 0;
    const motivos = [];

    const localH = normalizarTexto(h.localizacao);
    const servH = normalizarTexto(h.tipo_servico);

    if (localAtual && localH && localAtual === localH) {
      score += 4;
      motivos.push('mesmo_local');
    }

    if (servAtual && servH && servAtual === servH) {
      score += 3;
      motivos.push('mesmo_tipo_servico');
    }

    const similaridadeTitulo = intersecaoCount(tAtual, tokens((h.titulo || '') + ' ' + (h.descricao || '')));
    if (similaridadeTitulo >= 2) {
      score += 2;
      motivos.push('titulo_descricao_semelhantes');
    }

    const dAtual = dataMs(chamado?.data_hora_abertura || chamado?.data_abertura);
    const dH = dataMs(h?.data_hora_abertura || h?.data_abertura);
    const diffDias = dAtual > 0 && dH > 0 ? Math.abs((dAtual - dH) / 86400000) : null;
    if (diffDias !== null && diffDias <= 30) {
      score += 1;
      motivos.push('janela_30_dias');
    }

    if (refStr && String(h.id) === refStr) {
      score += 100;
      motivos.unshift('referencia_ia');
    }

    if (score >= 3 || (refStr && String(h.id) === refStr)) {
      ranked.push({
        ...h,
        _score_dup: score,
        _motivos_dup: motivos,
      });
    }
  }

  ranked.sort((a, b) => {
    if (b._score_dup !== a._score_dup) return b._score_dup - a._score_dup;
    return dataMs(a.data_hora_abertura || a.data_abertura) - dataMs(b.data_hora_abertura || b.data_abertura);
  });

  const unicos = [];
  const seen = new Set();
  for (const r of ranked) {
    const k = String(r.id);
    if (seen.has(k)) continue;
    seen.add(k);
    unicos.push(r);
  }

  return unicos.slice(0, 5);
}

const registrosIA = [];
for (const entrada of entradas) {
  const carga = extrairCarga(entrada.json || {});
  const regs = extrairRegistrosOrdenados(carga);
  if (regs.length === 0) registrosIA.push(carga);
  else registrosIA.push(...regs);
}

const saida = [];
const totalBase = originais.length;

for (let i = 0; i < totalBase; i++) {
  const base = originais[i]?.json || {};
  const original = base.chamado_atual || null;
  const historico = Array.isArray(base.historico_abertos) ? base.historico_abertos : [];
  const bruto = JSON.stringify(registrosIA[i] || {}).slice(0, 2000);
  const dados = registrosIA[i] && typeof registrosIA[i] === 'object' ? registrosIA[i] : {};

  const dupBase = dados.duplicidade && typeof dados.duplicidade === 'object' ? dados.duplicidade : {};
  const temEstrutura = pareceResultadoDuplicidade(dados);

  if (!temEstrutura) {
    saida.push({
      json: {
        ...base,
        chamado: original || { id: 'estrutura_invalida' },
        duplicidade: {
          eh_duplicado: false,
          chamado_referencia_id: null,
          caracteristicas_match: [],
          justificativa_para_fiscal: 'Resposta da IA sem estrutura esperada.'
        },
        'Duplicado?': {
          valor: 'Nao',
          caracteristicas: [],
          chamado_match: null
        },
        acao_duplicidade: {
          manter_chamado_id: original?.id || null,
          fechar_chamado_id: null,
          criterio: 'sem_duplicidade'
        },
        _dup_candidatos: [],
        _dup_idx_atual: 0,
        _dup_match_atual: null,
        _erro: true,
        tipo_erro: 'estrutura_resposta_inesperada',
        payload_ia_bruto: bruto
      }
    });
    continue;
  }

  const chamado = normalizarChamado(dados.chamado, original);
  const ehDuplicadoValor = dupBase.eh_duplicado !== undefined
    ? dupBase.eh_duplicado
    : (dados.eh_duplicado !== undefined ? dados.eh_duplicado : dados.potencial_duplicata);
  let ehDuplicadoIA = parseBool(ehDuplicadoValor) === true;

  const refRaw = dupBase.chamado_referencia_id !== undefined
    ? dupBase.chamado_referencia_id
    : dados.chamado_referencia_id;
  const refNum = Number(refRaw);
  let referenciaId = Number.isFinite(refNum) && refNum > 0 ? refNum : null;

const caracteristicas = Array.isArray(dupBase.caracteristicas_match)
    ? dupBase.caracteristicas_match
    : (Array.isArray(dados.caracteristicas_match) ? dados.caracteristicas_match : []);

  const justificativaBase = dupBase.justificativa_para_fiscal
    || dados.justificativa_para_fiscal
    || 'Sem justificativa';
  const testDupOverride = String(chamado?.titulo || '').includes('[TEST DUP]');
  if (testDupOverride) {
    ehDuplicadoIA = true;
    if (!referenciaId && historico.length > 0) {
      referenciaId = historico[0].id || referenciaId;
    }
  }


  let candidatos = montarCandidatos(chamado, historico, referenciaId, ehDuplicadoIA);
  let matchAtual = candidatos.length > 0 ? candidatos[0] : null;
  let ehDuplicadoEfetivo = ehDuplicadoIA && !!matchAtual;

  if (testDupOverride && !ehDuplicadoEfetivo && historico.length > 0) {
    candidatos = [historico[0]];
    matchAtual = candidatos[0];
    ehDuplicadoEfetivo = true;
  }

  let acao;
  if (ehDuplicadoEfetivo) {
    acao = escolherManterFechar(chamado, matchAtual);
  } else {
    acao = {
      manter: chamado?.id || null,
      fechar: null,
      criterio: 'sem_duplicidade',
    };
  }

  const justificativaFinal = ehDuplicadoEfetivo
    ? (justificativaBase + ` | ${candidatos.length} potencial(is) match(es) identificado(s).`)
    : justificativaBase;

  saida.push({
    json: {
      ...base,
      chamado: chamado.id ? chamado : (original || { id: 'desconhecido' }),
      duplicidade: {
        eh_duplicado: ehDuplicadoEfetivo,
        chamado_referencia_id: matchAtual?.id || referenciaId,
        caracteristicas_match: caracteristicas,
        justificativa_para_fiscal: justificativaFinal
      },
      'Duplicado?': {
        valor: ehDuplicadoEfetivo ? 'Sim' : 'Nao',
        caracteristicas: caracteristicas,
        chamado_match: ehDuplicadoEfetivo ? candidatos.map(c => c.id) : []
      },
      acao_duplicidade: {
        manter_chamado_id: acao.manter,
        fechar_chamado_id: acao.fechar,
        criterio: acao.criterio
      },
      _dup_candidatos: candidatos,
      _dup_idx_atual: 0,
      _dup_match_atual: matchAtual,
      _erro: false
    }
  });
}

return saida;

const MODO_TESTE = false;

function formatChamadoResumo(c) {
  if (!c) return '-';
  return [
    `ID: ${c.id || 'N/A'}`,
    `Status: ${c.status_nome || c.status || 'N/A'}`,
    `Titulo: ${c.titulo || 'N/A'}`,
    `Tipo servico: ${c.tipo_servico || 'N/A'}`,
    `Localizacao: ${c.localizacao || 'N/A'}`,
    `Abertura: ${c.data_hora_abertura || c.data_abertura || 'N/A'}`,
    `Descricao: ${(c.descricao || 'N/A').slice(0, 400)}`,
  ].join(' | ');
}

return $input.all().map((entrada) => {
  const item = entrada.json || {};
  const chamado = item.chamado || {};
  const dup = item.duplicidade || {};
  const acao = item.acao_duplicidade || {};

  const candidatos = Array.isArray(item._dup_candidatos) ? item._dup_candidatos : [];
  const idxAtual = Number(item._dup_idx_atual || 0);
  const matchAtual = item._dup_match_atual || candidatos[idxAtual] || null;

  const chamadoDecisaoId = chamado.id || null;
  const chamadoFecharId = acao.fechar_chamado_id || chamado.id || null;
  const chamadoManterId = acao.manter_chamado_id || dup.chamado_referencia_id || chamado.id || null;
  const chaveDuplicidade = ['DUP', chamadoDecisaoId || 'NA', chamadoFecharId || 'NA', chamadoManterId || 'NA', idxAtual].join('-');

  const header = '[TRIAGEM_IA][PENDENTE_DECISAO_DUPLICIDADE]';
  const motivoIA = dup.justificativa_para_fiscal || 'Sem justificativa';
  const totalMatches = candidatos.length;
  const matchLinhaAtual = matchAtual
    ? `Match em analise agora (${idxAtual + 1}/${totalMatches}): ${formatChamadoResumo(matchAtual)}`
    : 'Match em analise agora: N/A';

  const listaCompleta = totalMatches > 0
    ? candidatos.map((m, i) => `${i + 1}. ${formatChamadoResumo(m)} | Motivos: ${(m._motivos_dup || []).join(', ') || 'N/A'}`).join('\n')
    : 'Nenhum match adicional mapeado.';

  const mensagem = [
    header,
    `Chamado analisado: ${formatChamadoResumo(chamado)}`,
    `Motivo da marcacao de duplicidade: ${motivoIA}`,
    matchLinhaAtual,
    `Regra de fechamento se confirmar: manter #${chamadoManterId || 'N/A'} e fechar #${chamadoFecharId || 'N/A'}`,
    '',
    'Dados completos de todos os matches identificados nesta triagem:',
    listaCompleta,
    '',
    'Decisao do fiscal via links abaixo (cada link vincula chamado_id e match_id para evitar conflito):'
  ].join('\n');

  return {
    json: {
      ...item,
      _modo_teste: MODO_TESTE,
      _chamado_id: chamadoDecisaoId,
      _chamado_fechar_id: chamadoFecharId,
      _chamado_manter_id: chamadoManterId,
      _chamado_ref_id: chamadoManterId,
      _dup_chave: chaveDuplicidade,
      _dup_match_atual: matchAtual,
      _dup_idx_atual: idxAtual,
      _mensagem_followup_fiscal: mensagem,
      _matchs_detalhados_texto: listaCompleta,
    }
  };
});

let saida = [];
for (const item of $input.all()) {
  let json = item.json;
  let chamado = json.chamado;
  if (!chamado && json._chamado_id) { chamado = { id: json._chamado_id }; }
  saida.push({ json: { chamado: chamado || json, origem: json.acao === 'SEGUE_PARA_CLASSIFICACAO' ? 'fiscal_rejeitou_duplicidade' : 'nao_duplicado' } });
}
return saida;

