parameters.jsCode:
const originais = $('13. Preparar Dados para Classificacao').all();

return $input.all().map((item, idx) => {
  try {
    let dados = item.json;
    const respostaBruta = JSON.stringify(dados).slice(0, 2000);

    if (dados?.content?.parts?.[0]?.text) {
      dados = JSON.parse(dados.content.parts[0].text);
    }
    if (dados?.message?.content) {
      try { dados = JSON.parse(dados.message.content); } catch(e) {}
    }

    const chamadoOriginal = originais[idx]?.json?.chamado || item.json?.chamado || { id: 'desconhecido' };
    const classificacao = String(dados.classificacao || '').toUpperCase();
    const executor = String(dados.executor || '').toUpperCase();

    const validoClassificacao = ['OBRA', 'MANUTENCAO'].includes(classificacao);
    const validoExecutor = ['DDI_DG', 'DEMO', 'SOB_DEMANDA'].includes(executor);

    if (!validoClassificacao || !validoExecutor) {
      return {
        json: {
          chamado: chamadoOriginal,
          classificacao: 'ERRO',
          executor: 'ERRO',
          erro: 'Resposta da IA com classificacao/executor fora do dominio esperado.',
          tipo_erro: 'resposta_classificacao_invalida',
          resposta_ia_bruta: respostaBruta
        }
      };
    }

    return {
      json: {
        chamado: chamadoOriginal,
        classificacao,
        executor,
        justificativa_tecnica: dados.justificativa_tecnica || 'Sem justificativa',
        palavras_chave: dados.palavras_chave_identificadas || []
      }
    };
  } catch (error) {
    return {
      json: {
        chamado: originais[idx]?.json?.chamado || { id: 'desconhecido' },
        classificacao: 'ERRO',
        executor: 'ERRO',
        erro: error.message,
        tipo_erro: 'parse_json_classificacao',
        resposta_ia_bruta: JSON.stringify(item.json).slice(0, 2000)
      }
    };
  }
});

const entrada = $json || {};
const body = entrada.body && typeof entrada.body === 'object' ? entrada.body : entrada;

const eventoTipo = String(
  body.event ??
  body.evento ??
  body.payload?.event ??
  body.payload?.evento ??
  ''
).toLowerCase().trim();

const ticketIdRaw =
  body.ticket_id ??
  body.items_id ??
  body.id ??
  body.ticket?.id ??
  body.payload?.ticket_id ??
  body.payload?.items_id ??
  body.payload?.id ??
  body.input?.id ??
  body.item?.id ??
  null;

const ticketIdNum = Number(ticketIdRaw);

if (!Number.isFinite(ticketIdNum) || ticketIdNum <= 0) {
  return [{
    json: {
      _webhook_evento_valido: false,
      _ticket_id_evento: null,
      _webhook_evento_tipo: eventoTipo || null,
      _webhook_payload: body,
      _webhook_ticket_id_raw: ticketIdRaw ?? null,
    },
  }];
}

return [{
  json: {
    _webhook_evento_valido: true,
    _ticket_id_evento: ticketIdNum,
    _webhook_evento_tipo: eventoTipo || null,
    _webhook_payload: body,
    _webhook_ticket_id_raw: ticketIdRaw,
  },
}];

const candidatos = Array.isArray($json._dup_candidatos) ? $json._dup_candidatos : [];
const idxAtual = Number($json._dup_idx_atual || 0);
const proximoIdx = idxAtual + 1;

function dataMs(valor) {
  const d = new Date(valor || '');
  return Number.isNaN(d.getTime()) ? 0 : d.getTime();
}

function escolherManterFechar(chamadoAtual, candidato) {
  const atualId = chamadoAtual?.id || null;
  const candId = candidato?.id || null;

  const atualStatus = Number(chamadoAtual?.status_num || 0);
  const candStatus = Number(candidato?.status_num || 0);
  const emProcessamento = new Set([2, 3, 4]);

  if (candId && emProcessamento.has(candStatus) && !emProcessamento.has(atualStatus)) {
    return { manter: candId, fechar: atualId, criterio: 'manter_em_processamento' };
  }

  if (atualId && emProcessamento.has(atualStatus) && !emProcessamento.has(candStatus)) {
    return { manter: atualId, fechar: candId, criterio: 'manter_em_processamento' };
  }

  const dAtual = dataMs(chamadoAtual?.data_hora_abertura || chamadoAtual?.data_abertura);
  const dCand = dataMs(candidato?.data_hora_abertura || candidato?.data_abertura);

  if (dCand > 0 && dAtual > 0) {
    if (dCand <= dAtual) {
      return { manter: candId, fechar: atualId, criterio: 'manter_mais_antigo' };
    }
    return { manter: atualId, fechar: candId, criterio: 'manter_mais_antigo' };
  }

  return { manter: candId || atualId, fechar: atualId, criterio: 'manter_referencia_ia' };
}

if (proximoIdx < candidatos.length) {
  const proximo = candidatos[proximoIdx];
  const acao = escolherManterFechar($json.chamado || {}, proximo);

  return [{
    json: {
      ...$json,
      _dup_idx_atual: proximoIdx,
      _dup_match_atual: proximo,
      _chamado_manter_id: acao.manter,
      _chamado_fechar_id: acao.fechar,
      _chamado_ref_id: acao.manter,
      acao_duplicidade: {
        manter_chamado_id: acao.manter,
        fechar_chamado_id: acao.fechar,
        criterio: acao.criterio,
      },
      duplicidade: {
        ...($json.duplicidade || {}),
        chamado_referencia_id: proximo.id,
        justificativa_para_fiscal: (($json.duplicidade?.justificativa_para_fiscal || 'Possivel duplicidade') + ' | Reavaliando candidato ' + (proximoIdx + 1) + '/' + candidatos.length),
      },
      _acao_pos_rejeicao: 'avaliar_proximo',
    }
  }];
}

return [{
  json: {
    ...$json,
    _acao_pos_rejeicao: 'seguir_classificacao',
  }
}];

// Detecta de qual trigger veio a execucao
let modo = 'INICIAL';
let ticketIdEvento = null;
let eventoTipo = null;

try {
  const wh = $('T2. Webhook GLPI (Novo Chamado)').first()?.json;
  if (wh) {
    const body = wh.body && typeof wh.body === 'object' ? wh.body : wh;
    const evento = String(body.event ?? body.evento ?? body.payload?.event ?? '').toLowerCase().trim();
    const idRaw = body.ticket_id ?? body.items_id ?? body.id ?? body.ticket?.id ?? body.payload?.ticket_id ?? body.payload?.id;
    const idNum = Number(idRaw);
    if (Number.isFinite(idNum) && idNum > 0) {
      modo = 'INCREMENTAL';
      ticketIdEvento = idNum;
      eventoTipo = evento || 'new';
    }
  }
} catch(e) {}

try {
  const sc = $('T3. Schedule 06h/12h/18h').first()?.json;
  if (sc && sc.timestamp && modo === 'INICIAL') modo = 'SCHEDULE';
} catch(e) {}

return [{ json: { modo_execucao: modo, ticket_id_evento: ticketIdEvento, evento_tipo: eventoTipo, iniciado_em: new Date().toISOString() } }];

const ctx = $('N1. Identificar Modo').first().json;
const total = Number($json.total ?? 0);
let modo = ctx.modo_execucao;
if (total === 0) modo = 'INICIAL';
return [{ json: { ...ctx, modo_execucao: modo, total_no_bd: total, forcou_inicial: total === 0 && ctx.modo_execucao !== 'INICIAL' } }];

const STATUS_LABELS = { 1:'Novo', 2:'Atribuido', 3:'Planejado', 4:'Pendente', 5:'Solucionado', 6:'Fechado' };
const DIAS_RECORTE = 90;
const ctx = $('N3. Resolver Modo Final').first().json;
const corte = new Date(Date.now() - DIAS_RECORTE * 86400000);

function statusNumero(s) {
  if (typeof s === 'number') return s;
  const t = String(s||'').toLowerCase();
  if (t.includes('novo')||t==='1') return 1;
  if (t.includes('atribu')||t==='2') return 2;
  if (t.includes('planejad')||t==='3') return 3;
  if (t.includes('pendent')||t==='4') return 4;
  if (t.includes('soluc')||t.includes('finaliz')||t==='5') return 5;
  if (t.includes('fechado')||t.includes('close')||t==='6') return 6;
  return Number(s) || null;
}

function limpaHtml(s){ return String(s||'').replace(/<[^>]*>/g,'').trim(); }

function normalizar(c){
  const id = Number(c['2'] ?? c.id);
  const status_num = statusNumero(c['12'] ?? c.status);
  const dataAbertura = c['15'] ?? c.date ?? null;
  const dataMod = c['19'] ?? c.date_mod ?? dataAbertura;
  return {
    id,
    titulo: c['1'] ?? c.name ?? '',
    descricao: limpaHtml(c['21'] ?? c.content ?? ''),
    tipo_servico: String(c['14'] ?? c.itilcategories_id ?? ''),
    localizacao: String(c['83'] ?? c.locations_id ?? ''),
    solicitante: String(c['4'] ?? c.users_id_recipient ?? ''),
    email_solicitante: String(c['22'] ?? ''),
    status_num, status_nome: STATUS_LABELS[status_num] || 'Desconhecido',
    data_abertura: dataAbertura, data_ultima_mudanca: dataMod,
  };
}

let lista = [];
for (const item of $input.all()) {
  const d = item.json;
  if (Array.isArray(d?.data)) lista.push(...d.data);
  else if (Array.isArray(d)) lista.push(...d);
  else if (d && typeof d === 'object') lista.push(d);
}

let normalizados = lista.map(normalizar).filter(c => Number.isFinite(c.id) && c.id > 0);
normalizados = normalizados.filter(c => {
  if ([1,4].includes(c.status_num)) return true;
  if ([2,3,5,6].includes(c.status_num)) {
    const d = new Date(c.data_abertura);
    return !isNaN(d) && d >= corte;
  }
  return false;
});

return normalizados.map(c => ({ json: { chamado: c, modo: ctx.modo_execucao } }));

// Filtra chamados Novo (1) e Pendente (4) ainda nao triados.
// REGRA: SCHEDULE NAO dispara triagem IA — apenas atualiza o BD.
// Triagem IA acontece via webhook (T2) ou manual (T1).
const ctx = $('N3. Resolver Modo Final').first().json;
if (ctx.modo_execucao === 'SCHEDULE') return [];

const items = $input.all();
const saida = [];
for (const it of items) {
  const upsert = it.json;
  const allE1 = $('E1. Estruturar Chamados').all();
  const orig = allE1.find(x => Number(x.json.chamado.id) === Number(upsert.id));
  if (!orig) continue;
  const c = orig.json.chamado;

  if (![1,4].includes(c.status_num)) continue;
  if (upsert.triagem_status && upsert.triagem_status !== 'PENDENTE') continue;
  if (upsert.em_aprovacao_fiscal === true) continue;

  saida.push({ json: { chamado: c } });
}
return saida;

// Monta payload para IA e reutiliza em tentativas de reprocesso
const entrada = $input.all();
const retryPayload = entrada[0]?.json || {};
const veioDeRetry = !!retryPayload.chamado_atual && Array.isArray(retryPayload.historico_abertos);

if (veioDeRetry) {
  return [{
    json: {
      ...retryPayload,
      _retry_dedup: Number(retryPayload._retry_dedup || 0) + 1,
    }
  }];
}

const itensHist = entrada.map(i => i.json);
const atual = $('L1. SplitInBatches (3)').item.json.chamado;
return [{
  json: {
    chamado_atual: atual,
    historico_abertos: itensHist,
    _retry_dedup: 0,
  }
}];

function tryParse(t){ if (typeof t !== 'string') return null; try { return JSON.parse(t);} catch { return null; } }
function extrair(j){
  let d = j;
  const t1 = d?.content?.parts?.[0]?.text;
  if (typeof t1 === 'string') { const p = tryParse(t1); if (p) d = p; }
  const t2 = d?.message?.content;
  if (typeof t2 === 'string') { const p = tryParse(t2); if (p) d = p; }
  return d;
}
function pBool(v){
  if (typeof v === 'boolean') return v;
  if (typeof v === 'string') return ['true','1','sim','yes'].includes(v.toLowerCase().trim());
  return false;
}
const saida = [];
for (const it of $input.all()) {
  const r = extrair(it.json);
  const payload = $('D2. Montar Payload IA').item.json;
  const atual = payload.chamado_atual || {};
  const historico = Array.isArray(payload.historico_abertos) ? payload.historico_abertos : [];

  const iaOk = !!r && typeof r === 'object';
  const dup = iaOk ? (r.duplicidade || {}) : {};
  const refIdNum = Number(dup.chamado_referencia_id);
  const ref = Number.isFinite(refIdNum) ? (historico.find(h => Number(h.id) === refIdNum) || null) : null;

  saida.push({
    json: {
      chamado: { ...atual, ...(iaOk ? (r.chamado || {}) : {}) },
      duplicidade: {
        eh_duplicado: iaOk ? pBool(dup.eh_duplicado) : null,
        chamado_referencia_id: Number.isFinite(refIdNum) ? refIdNum : null,
        chamado_referencia: ref ? {
          id: ref.id,
          titulo: ref.titulo,
          status_nome: ref.status_nome,
          descricao: ref.descricao,
          localizacao: ref.localizacao,
          solicitante: ref.solicitante,
          email_solicitante: ref.email_solicitante,
        } : null,
        justificativa_para_fiscal: dup.justificativa_para_fiscal || (iaOk ? 'Sem justificativa' : 'Falha ao interpretar resposta da IA'),
        caracteristicas_match: Array.isArray(dup.caracteristicas_match) ? dup.caracteristicas_match : [],
      },
      _ia_ok: iaOk,
      _retry_dedup: Number(payload._retry_dedup || 0),
    }
  });
}
return saida;

